  "price.be.plain.any": "Bei {old} macht jeder {item} nach Mehrwertsteuer und Zutaten schon Verlust ({m}), also ist der neue Preis besser, egal was mit den Verkäufen passiert.",
  "price.be.plain.rise": "Bei {price} bringt jeder {item} nach Mehrwertsteuer und Zutaten {new} statt {old}, also: {words}. Verlieren Sie mehr, stehen Sie schlechter da.",
  "price.be.plain.cut": "Bei {price} bringt jeder {item} nach Mehrwertsteuer und Zutaten {new} statt {old}, also: {words}. Verkaufen Sie weniger, stehen Sie schlechter da.",
  "price.worst.maths": "Vorsichtige Schätzung: {u} pro Woche × {m} = {wn}; {wn} {vsOld} = {dw} pro Woche; × {days} Tage ÷ 7 = {wl}",
